package cleanup

import (
	"fmt"
	"io/fs"
	"path/filepath"
	"strings"
)

// cacheNames are directories that are regenerated by `terraform init` / `npm install`.
var cacheNames = map[string]bool{".terraform": true, "node_modules": true}

// cacheMaxDepth matches `find -maxdepth 4` in the original script.
const cacheMaxDepth = 4

// findCaches returns cache directories under root, not descending into them.
func findCaches(root string) []string {
	var found []string
	_ = filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil || !d.IsDir() {
			return nil
		}
		rel, _ := filepath.Rel(root, path)
		depth := 0
		if rel != "." {
			depth = strings.Count(rel, string(filepath.Separator)) + 1
		}
		if depth > 0 && cacheNames[d.Name()] {
			found = append(found, path)
			return filepath.SkipDir
		}
		if depth >= cacheMaxDepth {
			return filepath.SkipDir
		}
		return nil
	})
	return found
}

// dirSize sums the apparent size of regular files under dir.
func dirSize(dir string) int64 {
	var total int64
	_ = filepath.WalkDir(dir, func(_ string, d fs.DirEntry, err error) error {
		if err != nil || !d.Type().IsRegular() {
			return nil
		}
		if info, err := d.Info(); err == nil {
			total += info.Size()
		}
		return nil
	})
	return total
}

// humanSize formats bytes like `du -h`.
func humanSize(n int64) string {
	const unit = 1024
	if n < unit {
		return fmt.Sprintf("%dB", n)
	}
	div, exp := int64(unit), 0
	for m := n / unit; m >= unit; m /= unit {
		div *= unit
		exp++
	}
	return fmt.Sprintf("%.1f%c", float64(n)/float64(div), "KMGTPE"[exp])
}
